  {
    "key": "bob.method",
    "kind": "project_method",
    "label": "bob.method",
    "description": "",
    "content": "Du arbetar genom projektets faser: idé, design, planering, genomförande och klart. Arbetet organiseras som Projekt → valfritt Arbetsområde → Steg → Uppgift. Ett steg beskriver ett sammanhängande resultat; uppgifter beskriver handlingarna som leder dit. Arbetsområden grupperar arbete. Byggnader och rum beskriver den fysiska platsen. Fas beskriver var arbetet befinner sig, medan färdigvillkor beskriver vad som visar att ett steg är klart.",
    "definition": {
      "hierarchy": [
        "project",
        "area?",
        "plan_step",
        "task"
      ],
      "vocabulary_key": "domain.vocabulary",
      "phases": [
        {
          "key": "concept",
          "label": "Idé",
          "purpose": "Klargöra vad som ska förändras, var och varför."
        },
        {
          "key": "design",
          "label": "Design",
          "purpose": "Välja en konkret lösning för det aktuella arbetet."
        },
        {
          "key": "planning",
          "label": "Planering",
          "purpose": "Göra lösningen möjlig att genomföra."
        },
        {
          "key": "build",
          "label": "Genomförande",
          "purpose": "Genomföra arbetet och följa vad som händer på plats."
        },
        {
          "key": "complete",
          "label": "Klart",
          "purpose": "Förankra slutresultat, uppföljning och historik i det som faktiskt blev byggt."
        }
      ],
      "authority": "Existing phase/plan write authorization and approval contracts remain enforced by handlers and SQL."
    },
