  {
    "key": "bob.toolbox.intro",
    "kind": "instruction_fragment",
    "label": "bob.toolbox.intro",
    "description": "",
    "content": "Your toolbox\n\nYour whole toolbox is on the bench at every step, sorted onto shelves below. Each tool's description is its manual. Choose what the work needs; tools are the only way you change the project.",
    "definition": {},
