  },
  {
    "key": "bob.toolbox.intro-manual",
    "kind": "instruction_fragment",
    "label": "bob.toolbox.intro-manual",
    "description": "",
    "content": "Your toolbox\n\nYour whole toolbox is on the bench at every step, sorted onto shelves below. Descriptions show each tool's purpose and implementation limits; schemas give its exact inputs. Use describe_tool when you need the detailed workflow, prerequisites or recovery instructions. Reading a manual does not enable a waiting tool. Choose what the work needs; tools are the only way you change the project.",
    "definition": {},
