  {
    "key": "bob.tools",
    "kind": "tool_contract",
    "label": "bob.tools",
    "description": "",
    "content": "",
    "definition": {
      "catalog": [
        {
          "name": "archive_project_area",
          "description": "Archive an Area that is finished or no longer used, or restore an archived Area.",
          "how_to": "Archiving keeps the Area, its history and completed work, and takes it out of active planning. Unfinished Tasks must be moved or finished first, and a pending plan proposal that uses the Area must be resolved; the server refuses otherwise. Read the Area and pass its current updated_at.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "archive_project_measurement",
          "description": "Archive or restore an existing project measurement.",
          "how_to": "Read its current revision. Archive preserves history and exposes stale evidence to dependent drawings. Do not create a replacement measurement just to remove an obsolete one.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "attach_project_image",
          "description": "Attach an existing image to the relevant project work.",
          "how_to": "Use an exact ready image ID. Reuse its bytes rather than uploading again. Link to the correct target identity; plan_step and step are distinct.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "audit_project_plan",
          "description": "Audit the current approved living plan against authorised project evidence with the read-only mini compiler and nano reviewer.",
          "how_to": "Call with no arguments. The server resolves the current approved living plan and revision. Use the returned review to identify representation/evidence problems. This tool never writes, approves or links Tasks.",
          "schema_version": 1,
          "always_load": true,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "cancel_drawing_request",
          "description": "Cancel the initiating member's drawing request and fence late saves.",
          "how_to": "Only on the owner's instruction to stop that request. Read its exact id/revision first. The database checks current member and original initiator. Completed Artifacts are not deleted or relabelled cancelled.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "check_construction_draft",
          "description": "Check an exact saved construction for supported geometry, material dimensions and joint consistency.",
          "how_to": "Read or save a current construction first. Check its exact Artifact ID and revision. This server check supports uncut wooden boxes at orthogonal rotations and planar screwed/glued butt-joint concepts. Correct issues by revising the same draft. Compare bounds and part count with the original requirements. concept_ready is not fabrication_ready: product instructions, fastener layout, strength, stability, cutting and publication remain separate. Failed or stale reads cannot approve anything.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "compile_project_plan",
          "description": "Compile Bob's plan intent into exact Steps/Requirements and return nano's advisory review to Bob. Read-only; Bob decides corrections and saving.",
          "how_to": "Pass only plan_intent for an initial plan or broad replan. For a focused change use edit_project_plan, preserving unrelated work mechanically. The server binds the current revision. Mini compiles and nano advises; Bob assesses objections. Correct server errors, then save a sound proposal with save_compiled_project_plan. Task candidates contain only ownership changes, staged with the proposal and applied on approval. Use remaining_attempts; do not ask again for granted proposal scope.",
          "schema_version": 1,
          "always_load": true,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "consult_plan_assistant",
          "description": "Ground/compile Bob's project-manager plan or audit the current living plan with read-only mini/nano assistants. They never decide strategy or write project data.",
          "how_to": "Bob owns the project strategy. For a new/revised plan, pass mode=compile_plan, the exact current approved revision (0 when none) and Bob's concise plan_intent. The mini compiler may atomize Completion Requirements, match exact existing Task/evidence candidates and produce the normal proposal shape; the nano reviewer checks semantic fit. For an existing plan use audit_plan with plan_intent=null. Treat output as advisory. Do not save a known review error. task_candidates are suggestions only, never persisted Step↔Task links. A proposal does not create those links; after approval use link_project_plan_task and only report a Task as linked after a successful write receipt. The assistants never authorize a write; Bob must use the normal propose/decision/evidence/task tools.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": false
        },
        {
          "name": "create_project_room_layout",
          "description": "Create the existing two-rectangular-room layout with one shared wall and one linked storage-box drawing. Not a general house or furniture layout.",
          "how_to": "Reuse exact Building/Space/element identities, one selected target and a pinned furniture artifact. Room footprint checks do not check doors, circulation or height. This tool cannot create additional arbitrary rooms/furniture. Keep source revisions and measurements. A change is saved only with a successful receipt.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "decide_project_plan",
          "description": "Approve or reject one exact living Project Plan proposal. Approval changes the current plan; rejection leaves the current approved plan unchanged.",
          "how_to": "Read the proposal and current approved revision. The current owner must explicitly approve it or instruct this exact edit to be applied; do not require the same permission twice. A request for suggestions alone does not approve a plan, nor does approval of a specific edit authorise unrelated strategy. A stale proposal conflicts. Staged Task ownership is applied atomically on approval.",
          "schema_version": 1,
          "always_load": true,
          "preload_phases": [
            "concept",
            "design",
            "planning",
            "build"
          ],
          "active": true
        },
        {
          "name": "delete_project_build_day",
          "description": "Delete a build day that will not happen.",
          "how_to": "Removes the day, its sign-ups and its scheduled Task links; the Tasks themselves stay. Mention it to the owner when people had signed up. Read the build day with read_project_work(build_day) and pass its current updated_at.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "delete_project_task",
          "description": "Delete a Task that no longer belongs to the project.",
          "how_to": "Deletes the Task with its checkpoints, assignments, dependencies, needs, build-day scheduling and image attachments. Completed Tasks are project history and are kept. Prefer revising a Task over deleting and recreating it. Read the Task and pass its current updated_at.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "delete_shopping_item",
          "description": "Remove an item from the Shopping list.",
          "how_to": "For items no longer needed or added by mistake. A linked material requirement stays and only loses its Shopping link. Read Shopping with read_project_work(shopping) first.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "derive_cad_material_requirement",
          "description": "Derive a versioned blank material requirement from a saved CAD drawing or construction checkpoint.",
          "how_to": "Read the exact current drawing/construction, target and existing requirements. Choose an actual used definition and blank quantity mode; the server counts instances and copies computed dimensions. Preserve existing requirement IDs. Construction needs pin the construction/material revisions and are concept quantities: raw-stock fit, kerf, grain, hardware and access remain open, so stock/reuse allocations and Shopping are blocked. Ordinary CAD requirements retain their existing allocation/publish path. Read the saved requirement to verify its exact source and quantity.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [
            "planning",
            "build"
          ],
          "active": true
        },
        {
          "name": "check_construction_cut_fit",
          "description": "Check rectangular blank placement against explicit candidate sheets with kerf, trim and grain.",
          "how_to": "Read the exact current construction and material pins. Supply candidate sheet dimensions/count, kerf, trim per edge and sheet grain with an honest specification/design-choice basis and note. Name each used definition once with its local in-plane grain axis; null remains unknown and none is an explicit no-grain constraint. Code derives ALL actual instance blanks and returns placements, executable guillotine cuts and offcuts. Feasible is geometric evidence for these inputs only, not verified physical stock, product suitability, an optimal purchase count or a saved plan. no_layout_found/search_limit are not general impossibility proofs. Keep existing requirement IDs/history. Allocation and Shopping stay blocked until a persisted cut plan is bound to current real stock/product capacity.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [
            "planning",
            "build"
          ],
          "active": true
        },
        {
          "name": "derive_construction_lists",
          "description": "Derive concept part quantities, blank cut dimensions and a proposed assembly order from the exact checked construction.",
          "how_to": "Read/check the exact current construction. assembly_dependencies=[] reports the missing order; otherwise specify every joint once with prerequisite joint IDs. The code counts actual instances and validates a separate acyclic assembly graph. Blank cuts are not a raw-stock layout, product approval or saved delivery. Preserve explicit raw-format, kerf, grain, hardware and assembly-access gaps. Save blank needs through derive_cad_material_requirement using this construction revision, then read_project_work(requirement) to verify. Shopping and stock/reuse allocation are blocked until cut fit is supported.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [
            "planning",
            "build"
          ],
          "active": true
        },
        {
          "name": "describe_project_image",
          "description": "Cache a short, unverified visual description of a viewed image.",
          "how_to": "Optional after viewing image pixels in this turn. Describe visible content only, max 500 characters; no private conversation details, instructions or inferred measurements. Helps later image selection. Never open images or request a separate vision call only to fill this cache. Not a verified project fact.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "design_project_cad",
          "description": "Collect and assess all drawing requirements, then construct and independently review CAD.",
          "how_to": "Read current construction drafts and check the exact revision. Pass that construction Artifact ID as artifact_id to design_project_cad. The server rechecks its current sources and renders the same geometry with dimensions and part IDs; no second designer construction is created. Original requirements, joints, materials, checks and pixels go to the independent reviewer. Only save_cad_design saves an approved candidate; verify its receipt, exact revision, work link and readback. Correct construction issues in the checkpoint; renderer annotation defects need a renderer repair. Unknown product or strength checks remain concept limitations.",
          "schema_version": 3,
          "always_load": false,
          "preload_phases": [
            "design"
          ],
          "active": true
        },
        {
          "name": "detach_project_image",
          "description": "Detach an image from an Area, Task, instruction step or plan Step.",
          "how_to": "The image stays in the project library; only this attachment goes. Use the exact image ID and the target_kind and target_id it is attached to.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "edit_project_plan",
          "description": "Prepare focused edits to the current plan while preserving unrelated Steps, criteria and Task ownership exactly.",
          "how_to": "Use exact current IDs and a bounded changes list. Read-only: creates an exact candidate for save_compiled_project_plan. Remove obsolete work explicitly instead of falsely marking a physical check complete. Save the proposal, then use decide_project_plan when the current owner request explicitly instructs applying this exact edit. A request for suggestions alone does not approve a change.",
          "schema_version": 1,
          "always_load": true,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "edit_project_room_layout",
          "description": "Move the shared wall, place the linked furniture, or explicitly refresh sources in an existing two-room layout. Does not change the furniture construction.",
          "how_to": "Read the exact layout and dependencies. A wall move derives both room widths from the fixed span. place_furniture changes placement only. refresh_sources adopts current source versions without changing geometry parameters. Preserve unused fields as null and report out-of-room/stale conflicts. A change is saved only with a successful receipt.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "ensure_drawing_gap_task",
          "description": "Reuse or create a Task for a canonical drawing requirement.",
          "how_to": "Read stable request/gap IDs and the current Plan revision first. The gap must reference an already shared canonical requirement. Reuses the requirement Task atomically across repeated calls and requests; never copies private collector text.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "finalize_project_image",
          "description": "Recover a previously uploaded pending image.",
          "how_to": "Use the pending media_id after upload succeeded but finalization failed. This never regenerates or uploads bytes. Storage metadata must match before the image becomes ready.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "generate_project_image",
          "description": "Generate, save and attach a project mockup or instruction image.",
          "how_to": "Read existing image metadata before generating. Supply relevant project facts in prompt, purpose proposal/instruction and an exact target. plan_step means a living-plan Step, step means a Task instruction step. A partial upload is not a ready image; preserve its media_id for recovery.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "inspect_building_projection",
          "description": "Inspect what mapped rooms lie vertically above or below a rectangular area in a saved multi-floor plan. Read-only; this is not a stair calculation.",
          "how_to": "Read the current exact source plan first. Projection preserves x/y; show full containment, partial overlap, envelope conflicts and unknown coverage. Empty mapped hits do not mean empty physical space. Floor/slab differences require known heights. For a staircase use an actual stair generator and disclose its shape limits.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [
            "design"
          ],
          "active": true
        },
        {
          "name": "inspect_stair_options",
          "description": "Compare straight or quarter-turn stairs with a square landing on a saved multi-floor plan. Read-only geometric study; not a rounded/winder stair generator.",
          "how_to": "Read current plan sources first. Compare one to four explicit parameter candidates; use returned exit, direction and headroom facts. Choose reversible design assumptions, but do not invent unknown floor or ceiling heights. Headroom is a stated study criterion, not a verified regulation. Checks cover full walking rectangles against a flat slab and rectangular opening; doors, beams, roof slopes, structure and safety remain unmodelled.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "link_drawing_gap",
          "description": "Link a drawing gap to existing project work.",
          "how_to": "Read the request revision and stable gap ID first. Use exact existing Task and Step IDs. Repeated linking is idempotent; existing links cannot be silently replaced. Do not publish private collector prose.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "link_project_drawing",
          "description": "Link or unlink a saved drawing and a project Step without redrawing.",
          "how_to": "Read the current drawing revision and plan Step IDs. Reuse the same drawing across relevant Steps. The project home shows saved drawings automatically. Planning is a phase; attach to the work the drawing describes. Read existing links using read_project_record_section with dataset drawing.",
          "schema_version": 1,
          "always_load": false,
          "preload_phases": [],
          "active": true
        },
        {
          "name": "link_project_plan_evidence",
          "description": "Link exact current project evidence to one Completion Requirement in the current approved living plan.",
          "how_to": "Use exact current project IDs/revisions. A resolves/refines/supersedes link may satisfy the requirement while conflicts marks it conflicted. Revisioned evidence pins the exact revision; if the source later changes the link becomes stale until reviewed. Do not manufacture evidence or use private conversation text as project evidence.",
          "schema_version": 1,
          "always_load": true,
          "preload_phases": [
            "concept",
            "design",
            "planning",
