  {
    "key": "schema.bob_cad_review",
    "kind": "response_schema",
    "label": "schema.bob_cad_review",
    "description": "",
    "content": "",
    "definition": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "verdict": {
          "type": "string",
          "enum": [
            "pass",
            "revise"
          ]
        },
        "summary": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000
        },
        "requirements": {
          "type": "array",
          "maxItems": 24,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "id": {
                "type": "string"
