  {
    "key": "schema.bob_plan_compilation",
    "kind": "response_schema",
    "label": "schema.bob_plan_compilation",
    "description": "",
    "content": "",
    "definition": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "summary": {
          "type": "string"
        },
        "reason": {
          "type": "string"
        },
        "steps": {
          "type": "array",
          "maxItems": 100,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "step_id": {
                "type": [
                  "string",
                  "null"
                ],
                "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$",
                "description": "Stable UUID from current plan when this is the same active/future Step; null for a new Step."
              },
              "title": {
                "type": "string"
              },
              "goal": {
                "type": "string"
              },
              "state": {
                "type": "string",
                "enum": [
                  "planned",
                  "active",
                  "blocked",
                  "completed"
                ]
              },
              "area_id": {
                "type": [
                  "string",
                  "null"
                ],
                "description": "Optional organisational Area. Null places the Step directly in the Project."
              },
              "phase": {
                "type": [
                  "string",
                  "null"
                ],
                "enum": [
                  "concept",
                  "design",
                  "planning",
                  "build",
                  "complete",
                  null
                ]
              },
              "responsible_kind": {
                "type": "string",
                "enum": [
                  "bob",
                  "person",
                  "unassigned"
                ],
                "description": "Who owns the work, not who is authorized to approve it. person uses an exact project person ID."
              },
              "responsible_person_id": {
                "type": [
                  "string",
                  "null"
                ],
                "description": "Exact bob.people ID when responsible_kind=person; otherwise null."
              },
              "notes": {
                "type": "string",
                "description": "Step Brief: Bob's concise self-prompt for this Step — purpose, focus, important constraints and what matters while working here. Keep it compact; project facts and Completion Requirements remain authoritative."
              },
              "requirements": {
                "type": "array",
                "maxItems": 20,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "requirement_id": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$",
                      "description": "Exact Requirement UUID from the current plan, never a Task ID; null for a new requirement."
                    },
                    "type": {
                      "type": "string",
                      "enum": [
                        "measurement",
                        "photo",
                        "decision",
                        "drawing",
                        "material_requirement",
                        "material_delivery",
                        "task",
                        "approval",
                        "check",
                        "other"
                      ]
                    },
                    "title": {
                      "type": "string"
                    },
                    "description": {
                      "type": "string"
                    },
                    "resolution": {
                      "type": "string",
                      "enum": [
                        "open",
                        "waived",
                        "not_applicable"
                      ]
                    },
                    "responsible_kind": {
                      "type": "string",
                      "enum": [
                        "bob",
                        "person",
                        "unassigned"
                      ],
                      "description": "Who owns the work, not who is authorized to approve it. person uses an exact project person ID."
                    },
                    "responsible_person_id": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "description": "Exact bob.people ID when responsible_kind=person; otherwise null."
                    },
                    "evidence_selector": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "kind": {
                          "type": "string",
                          "enum": [
                            "none",
                            "measurement",
                            "media",
                            "artifact",
                            "material_requirement",
                            "solution",
                            "task"
                          ]
                        },
                        "id": {
                          "type": [
                            "string",
                            "null"
                          ]
                        },
                        "subject": {
                          "type": [
                            "string",
                            "null"
                          ]
                        },
                        "area_id": {
                          "type": [
                            "string",
                            "null"
                          ]
                        }
                      },
                      "required": [
                        "kind",
                        "id",
                        "subject",
                        "area_id"
                      ],
                      "description": "Optional dynamic evidence selector. measurement may use exact measurement id, or exact subject plus optional Area. Other kinds require exact id. none has all nullable fields null."
                    }
                  },
                  "required": [
                    "requirement_id",
                    "type",
                    "title",
                    "description",
                    "resolution",
                    "responsible_kind",
                    "responsible_person_id",
                    "evidence_selector"
                  ]
                }
              }
            },
            "required": [
              "step_id",
              "title",
              "goal",
              "state",
              "area_id",
              "responsible_kind",
              "responsible_person_id",
              "notes",
              "requirements",
              "phase"
            ]
          }
        },
        "task_candidates": {
          "type": "array",
          "maxItems": 40,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "step_position": {
                "type": "integer",
                "minimum": 1,
                "maximum": 100
              },
              "task_id": {
                "type": "string"
              },
              "task_name": {
                "type": "string"
              },
              "reason": {
                "type": "string"
              }
            },
            "required": [
              "step_position",
              "task_id",
              "task_name",
              "reason"
            ]
          }
        },
        "observations": {
          "type": "array",
          "maxItems": 30,
          "items": {
            "type": "string"
          }
        }
      },
      "required": [
        "summary",
        "reason",
        "steps",
        "task_candidates",
        "observations"
      ]
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/plan-assistant.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "schema.bob_plan_compilation",
      "description": ""
    },
    "variables": []
  },
