  {
    "key": "schema.cad_arrays",
    "kind": "response_schema",
    "label": "schema.cad_arrays",
    "description": "",
    "content": "",
    "definition": {
      "type": "array",
      "maxItems": 64,
      "description": "Repeat templates for evenly spaced identical parts (studs, slats, joists, rungs). Each expands to instances <id>.1..<id>.<count>. Bind arrays/<id>/start/x|y|z|rx|ry|rz (first copy) and arrays/<id>/spacing_mm (centre-to-centre step along axis); do not bind the expanded instances. Copy N sits at start + (N-1) x spacing along axis.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id",
          "definition_id",
          "axis",
          "count"
        ],
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
          },
          "definition_id": {
            "type": "string",
            "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
          },
          "axis": {
            "type": "string",
            "enum": [
              "x",
              "y",
              "z"
            ]
          },
          "count": {
            "type": "integer",
            "minimum": 2,
            "maximum": 256
          }
        }
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/cad-arrays.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "schema.cad_arrays",
      "description": ""
    },
    "variables": []
  },
  {
    "key": "schema.cad_frames",
    "kind": "response_schema",
    "label": "schema.cad_frames",
    "description": "",
    "content": "",
    "definition": {
      "type": "array",
      "maxItems": 16,
      "description": "External-to-assembly transforms; every translation/rotation component names a parameter node. Room source_ref is parameter:<physical source node>; image source_ref is an exact opened image:<UUID>. Image camera directions and room compass axes are distinct. Null placement preserves unknown orientation/origin; required unknown transforms stop the request. Do not convert a reference image into measured truth. Local part, cut and view frames are supplied by the pinned engine convention.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
          },
          "kind": {
            "type": "string",
            "enum": [
              "room",
              "image"
            ]
          },
          "source_ref": {
            "type": "string"
          },
          "required": {
            "type": "boolean"
          },
          "reason": {
            "type": "string",
            "minLength": 1,
            "maxLength": 2000
          },
          "placement": {
            "anyOf": [
              {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "x": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  },
                  "y": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  },
                  "z": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  },
                  "rx": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  },
                  "ry": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  },
                  "rz": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  }
                },
                "required": [
                  "x",
                  "y",
                  "z",
                  "rx",
                  "ry",
                  "rz"
                ]
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "id",
          "kind",
          "source_ref",
          "required",
          "reason",
          "placement"
        ]
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/cad-frames.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
