    "key": "tools.archive_project_area",
    "kind": "tool_contract",
    "label": "Archive an Area that is finished or no longer used, or restore an archived Area.",
    "description": "",
    "content": "",
    "definition": {
      "name": "archive_project_area",
      "description": "Archive a finished or unused Area, or restore an archived one. History and completed work stay.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "area_id": {
            "type": "string"
          },
          "action": {
            "type": "string",
            "enum": [
              "archive",
              "restore"
            ]
          },
          "expected_updated_at": {
            "type": "string",
            "description": "The record's current updated_at, read just before this call."
          },
          "request_quote": {
            "type": "string",
            "description": "Exact 1–500 character quote from the CURRENT user message authorising this action, including a clear approval of an earlier option."
          }
        },
        "required": [
          "area_id",
          "action",
          "expected_updated_at",
          "request_quote"
        ]
