  {
    "key": "tools.check_construction_cut_fit",
    "kind": "tool_contract",
    "label": "Check rectangular blank placement against explicit candidate sheets with kerf, trim and grain.",
    "description": "",
    "content": "",
    "definition": {
      "name": "check_construction_cut_fit",
      "description": "Check actual rectangular blank placement for ALL instances in the exact current checked construction against explicit candidate sheet formats. Supply exact used material pins, sheet count, mm length/width/thickness, saw kerf, trim per edge, sheet grain direction and each definition’s LOCAL in-plane grain axis. null means unknown and blocks a layout; none is an explicit decision that grain imposes no constraint. Candidate dimensions/grain are supplied specifications or design choices with an honest basis/note, not verified physical stock. Code returns a bounded guillotine cutting layout with placements, cut order and offcuts, or a concrete gap. No summed-area shortcut or optimal purchase count. This read-only result is not saved and cannot unlock stock/reuse allocation or Shopping. Keep existing need identities and history.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "artifact_id": {
            "type": "string",
            "format": "uuid"
          },
          "revision": {
            "type": "integer",
            "minimum": 1,
            "maximum": 999999999
          },
          "candidates": {
            "type": "array",
            "minItems": 1,
            "maxItems": 8,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "id": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                },
                "material_id": {
                  "type": "string",
                  "format": "uuid"
                },
                "material_revision": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 999999999
                },
                "length_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0.000001,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "width_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0.000001,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "thickness_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0.000001,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "count": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 16
                },
                "kerf_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "trim_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "grain": {
                  "type": [
                    "string",
                    "null"
                  ],
                  "enum": [
                    "length",
                    "width",
                    "none",
                    null
                  ]
                },
                "basis": {
                  "type": "string",
                  "enum": [
                    "design_choice",
                    "provided_spec"
                  ]
                },
                "note": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 1000
                }
              },
              "required": [
                "id",
                "material_id",
                "material_revision",
                "length_mm",
                "width_mm",
                "thickness_mm",
                "count",
                "kerf_mm",
                "trim_mm",
                "grain",
                "basis",
                "note"
              ]
            }
          },
          "blank_grain": {
            "type": "array",
            "minItems": 1,
            "maxItems": 128,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "definition_id": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                },
                "axis": {
                  "type": [
                    "string",
                    "null"
                  ],
                  "enum": [
                    "x",
                    "y",
                    "z",
                    "none",
                    null
                  ]
                }
              },
              "required": [
                "definition_id",
                "axis"
              ]
            }
          }
        },
        "required": [
          "artifact_id",
          "revision",
          "candidates",
          "blank_grain"
        ]
      },
      "handler": "check_construction_cut_fit",
      "additional_description": "Read the exact current construction and material pins. Supply candidate sheet dimensions/count, kerf, trim per edge and sheet grain with an honest specification/design-choice basis and note. Name each used definition once with its local in-plane grain axis; null remains unknown and none is an explicit no-grain constraint. Code derives ALL actual instance blanks and returns placements, executable guillotine cuts and offcuts. Feasible is geometric evidence for these inputs only, not verified physical stock, product suitability, an optimal purchase count or a saved plan. no_layout_found/search_limit are not general impossibility proofs. Keep existing requirement IDs/history. Allocation and Shopping stay blocked until a persisted cut plan is bound to current real stock/product capacity.",
      "required_parameters": [
        "artifact_id",
        "revision",
        "candidates",
        "blank_grain"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/construction-draft.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Check rectangular blank placement against explicit candidate sheets with kerf, trim and grain.",
      "description": ""
    },
    "variables": []
  },
  {
    "key": "tools.check_construction_draft",
