  {
    "key": "tools.compose_cad_shell",
    "kind": "tool_contract",
    "label": "Combine separately saved CAD pieces into one shell drawing, and move, add, remove or update pieces in it.",
    "description": "",
    "content": "",
    "definition": {
      "name": "compose_cad_shell",
      "description": "Combine separately saved CAD drawings (rooms, walls, furniture) into one shell drawing, or move, add, remove or update a piece in an existing shell. The shell only places pieces; it never redraws or copies them. Positions are proposals unless the owner gave them.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "record_id",
          "expected_revision",
          "action",
          "title",
          "description",
          "assumptions",
          "area_id",
          "components",
          "component_key",
          "placement",
          "component",
          "request_quote"
        ],
        "properties": {
          "record_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Null only for action=create."
          },
          "expected_revision": {
            "type": "integer",
            "minimum": 0,
            "description": "0 for create; otherwise the shell revision you last read."
          },
          "action": {
            "type": "string",
            "enum": [
              "create",
              "place",
              "add",
              "remove",
              "adopt"
            ]
          },
          "title": {
            "type": [
              "string",
              "null"
            ],
            "maxLength": 200
          },
          "description": {
            "type": [
              "string",
              "null"
            ],
            "maxLength": 4000
          },
          "assumptions": {
            "type": [
              "string",
              "null"
            ],
            "maxLength": 3000
          },
          "area_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "components": {
            "type": [
              "array",
              "null"
            ],
            "minItems": 1,
            "maxItems": 64,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "component_key",
                "child_artifact_id",
                "child_revision",
                "x_mm",
                "y_mm",
                "z_mm",
                "rz",
                "placement_basis",
                "reason"
              ],
              "properties": {
                "component_key": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9_-]{0,39}$",
                  "description": "Stable short key, e.g. bedroom, bunk_bed."
                },
                "child_artifact_id": {
                  "type": "string",
                  "description": "Saved CAD drawing id from read_drawing_requests or a save receipt."
                },
                "child_revision": {
                  "type": [
                    "integer",
                    "null"
                  ],
                  "description": "Null pins the current saved revision."
                },
                "x_mm": {
                  "type": "integer",
                  "description": "East offset of the piece origin in the shell, whole mm."
                },
                "y_mm": {
                  "type": "integer",
                  "description": "North offset, whole mm."
                },
                "z_mm": {
                  "type": "integer",
                  "description": "Height offset, whole mm."
                },
                "rz": {
                  "type": "integer",
                  "enum": [
                    0,
                    90,
                    180,
                    270
                  ],
                  "description": "Rotation about the vertical axis, degrees."
                },
                "placement_basis": {
                  "type": "string",
                  "enum": [
                    "shared_origin",
                    "owner_placed",
                    "bob_decision"
                  ],
                  "description": "shared_origin: piece was planned in the shell coordinates (plan_cad_pieces). owner_placed: the owner said where. bob_decision: your reversible proposal."
                },
                "reason": {
                  "type": "string",
                  "maxLength": 500,
                  "description": "Why the piece sits here, in the owner's words where possible."
                }
              }
            },
            "description": "create only."
          },
          "component_key": {
            "type": [
              "string",
              "null"
            ],
            "description": "place, remove or adopt."
          },
          "placement": {
            "type": [
              "object",
              "null"
            ],
            "additionalProperties": false,
            "required": [
              "x_mm",
              "y_mm",
              "z_mm",
              "rz",
              "placement_basis",
              "reason"
            ],
            "properties": {
              "x_mm": {
                "type": "integer",
                "description": "East offset of the piece origin in the shell, whole mm."
              },
              "y_mm": {
                "type": "integer",
                "description": "North offset, whole mm."
              },
              "z_mm": {
                "type": "integer",
                "description": "Height offset, whole mm."
              },
              "rz": {
                "type": "integer",
                "enum": [
                  0,
                  90,
                  180,
                  270
                ],
                "description": "Rotation about the vertical axis, degrees."
              },
              "placement_basis": {
                "type": "string",
                "enum": [
                  "shared_origin",
                  "owner_placed",
                  "bob_decision"
                ],
                "description": "shared_origin: piece was planned in the shell coordinates (plan_cad_pieces). owner_placed: the owner said where. bob_decision: your reversible proposal."
              },
              "reason": {
                "type": "string",
                "maxLength": 500,
                "description": "Why the piece sits here, in the owner's words where possible."
              }
            },
            "description": "place only."
          },
          "component": {
            "type": [
              "object",
              "null"
            ],
            "additionalProperties": false,
            "required": [
              "component_key",
              "child_artifact_id",
              "child_revision",
              "x_mm",
              "y_mm",
              "z_mm",
              "rz",
              "placement_basis",
              "reason"
            ],
            "properties": {
              "component_key": {
                "type": "string",
                "pattern": "^[a-z][a-z0-9_-]{0,39}$",
                "description": "Stable short key, e.g. bedroom, bunk_bed."
              },
              "child_artifact_id": {
                "type": "string",
                "description": "Saved CAD drawing id from read_drawing_requests or a save receipt."
              },
              "child_revision": {
                "type": [
                  "integer",
                  "null"
                ],
                "description": "Null pins the current saved revision."
              },
              "x_mm": {
                "type": "integer",
                "description": "East offset of the piece origin in the shell, whole mm."
              },
              "y_mm": {
                "type": "integer",
                "description": "North offset, whole mm."
              },
              "z_mm": {
                "type": "integer",
                "description": "Height offset, whole mm."
              },
              "rz": {
                "type": "integer",
                "enum": [
