                  90,
                  180,
                  270
                ],
                "description": "Rotation about the vertical axis, degrees."
              },
              "placement_basis": {
                "type": "string",
                "enum": [
                  "shared_origin",
                  "owner_placed",
                  "bob_decision"
                ],
                "description": "shared_origin: piece was planned in the shell coordinates (plan_cad_pieces). owner_placed: the owner said where. bob_decision: your reversible proposal."
              },
              "reason": {
                "type": "string",
                "maxLength": 500,
                "description": "Why the piece sits here, in the owner's words where possible."
              }
            },
            "description": "add only."
          },
          "request_quote": {
            "type": "string",
            "description": "Exact quote from the CURRENT user message authorising this change."
          }
        }
      },
      "handler": "compose_cad_shell",
      "additional_description": "A shell places saved CAD pieces (rooms, walls, furniture) by reference: exact piece revision plus x/y/z in mm and a rotation of 0, 90, 180 or 270 degrees about z. action=create needs title, description, assumptions, area_id and components [{component_key,child_artifact_id,child_revision (null = current),x_mm,y_mm,z_mm,rz,placement_basis,reason}]. Pieces made by plan_cad_pieces share one origin: use 0,0,0,0 with placement_basis shared_origin. place moves one piece (component_key plus new placement); add/remove change the piece list; adopt re-pins a piece that has a newer saved revision. Use the returned revision as expected_revision next time. Positions the owner chose are owner_placed; never present a placement as measured. Cut lists and materials stay on the pieces.",
      "required_parameters": [
        "record_id",
        "expected_revision",
        "action",
        "title",
        "description",
        "assumptions",
        "area_id",
        "components",
        "component_key",
        "placement",
        "component",
        "request_quote"
      ],
