    "description": "",
    "content": "",
    "definition": {
      "name": "derive_cad_material_requirement",
      "description": "Create/revise a deterministic material requirement from one definition in a current saved CAD drawing or construction checkpoint. Quantity comes from the saved recipe and instance count. Preserve the existing requirement identity when updating it. Use pieces, length_x/y/z or area_xy/xz/yz (box blank dimensions); tube/cylinder length is length_z. Holes/notches do not reduce purchased blank quantity. Check actual stock/reuse specification and fit before allocation. Construction blank needs are concept quantities: stock/reuse allocation and Shopping are blocked until raw-stock fit is supported. CAD requirements retain the existing separate publish path.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "record_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "expected_revision": {
            "type": "integer",
            "minimum": 0
          },
          "expected_updated_at": {
            "type": [
              "string",
              "null"
            ]
          },
          "request_quote": {
            "type": "string"
          },
          "data": {
            "type": "object",
            "additionalProperties": true,
            "description": "name, category, area_id, task_id, waste_percent, purchase_increment, assumptions, artifact_id (drawing or construction), artifact_revision, target_revision, definition_id, quantity_mode, stock_allocations:[{id,revision,quantity}], component_allocations:[{id,revision,quantity}], change_note. No quantity, unit, method or basis input: these are server-derived. New record_id=null/revision=0; revise exact requirement UUID/current revision. expected_updated_at=null."
          }
        },
        "required": [
          "record_id",
          "expected_revision",
          "expected_updated_at",
          "request_quote",
          "data"
        ]
      },
      "handler": "derive_cad_material_requirement",
      "additional_description": "Read the exact current drawing/construction, target and existing requirements. Choose an actual used definition and blank quantity mode; the server counts instances and copies computed dimensions. Preserve existing requirement IDs. Construction needs pin the construction/material revisions and are concept quantities: raw-stock fit, kerf, grain, hardware and access remain open, so stock/reuse allocations and Shopping are blocked. Ordinary CAD requirements retain their existing allocation/publish path. Read the saved requirement to verify its exact source and quantity.",
