  {
    "key": "tools.derive_construction_lists",
    "kind": "tool_contract",
    "label": "Derive concept part quantities, blank cut dimensions and a proposed assembly order from the exact checked construction.",
    "description": "",
    "content": "",
    "definition": {
      "name": "derive_construction_lists",
      "description": "Derive a concept BOM, one blank cut row per actual instance and joint references from the exact current checked construction, without redesign or rendering. Code counts instances and copies the server-computed local mm dimensions. assembly_dependencies=[] leaves order unresolved; otherwise name every saved joint once and its prerequisite joints. Code rejects cycles in this separate order graph; it does not verify physical tool access. No raw-sheet purchase count, hardware count or stock reservation is inferred. Use derive_cad_material_requirement to save blank requirements from the same construction revision, then read them back. This read tool does not save lists or approve fabrication.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "artifact_id": {
            "type": "string",
            "format": "uuid"
          },
          "revision": {
            "type": "integer",
            "minimum": 1,
            "maximum": 999999999
          },
          "assembly_dependencies": {
            "type": "array",
            "maxItems": 1024,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "joint_id": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                },
                "depends_on": {
                  "type": "array",
                  "maxItems": 64,
                  "uniqueItems": true,
                  "items": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  }
                }
              },
              "required": [
                "joint_id",
                "depends_on"
              ]
            }
          }
        },
        "required": [
          "artifact_id",
          "revision",
          "assembly_dependencies"
        ]
      },
