  {
    "key": "tools.design_project_cad",
    "kind": "tool_contract",
    "label": "Collect and assess all drawing requirements, then construct and independently review CAD.",
    "description": "",
    "content": "",
    "definition": {
      "name": "design_project_cad",
      "description": "Delegate a requested CAD drawing to the CAD assistant. For a construction concept with parts, material revisions and typed joints, use save_construction_draft and check_construction_draft first; this drawing tool cannot replace that deliverable or repair catalog definitions. Images opened in this turn are reopened for the designer beside current project facts. Delegate drawing intake early; the collector can read facts and open relevant images. Return all missing inputs together; reuse existing Tasks/Steps or gather measurements in chat, then resume the same request_id. It has its own project, material, image and geometry tools and can inspect, render and repair repeatedly. Returns a checked candidate, not a saved drawing. Specify intent, coordinate/view directions and relevant object IDs; the assistant can fetch wider dependencies.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "request_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Resume this saved drawing request ID after complements. Null only for a new request. Preserve existing requirements unless the owner explicitly changes them. When the owner writes again about a request that stopped at its cost or call limit, call this immediately with that ID; the owner's new message renews the budget, which the server adds. Do not re-read requests, budgets or sources first."
          },
          "brief": {
            "type": "string"
          },
          "handoff": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "deliverable": {
                "type": "string",
                "minLength": 1,
                "maxLength": 2000
              },
              "requirements": {
                "type": "array",
                "minItems": 1,
                "maxItems": 24,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "id": {
                      "type": "string",
                      "pattern": "^[a-zA-Z0-9_-]{1,40}$"
                    },
                    "requirement": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 2000
                    },
                    "basis": {
                      "type": "string",
                      "enum": [
                        "user_request",
                        "project_record",
                        "working_assumption"
                      ]
                    },
                    "source_ref": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "maxLength": 500
                    }
                  },
                  "required": [
                    "id",
                    "requirement",
                    "basis",
                    "source_ref"
                  ]
                }
              },
              "coordinates": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "origin": {
                    "type": [
                      "string",
                      "null"
                    ],
                    "maxLength": 500
                  },
                  "positive_x": {
                    "type": [
                      "string",
                      "null"
                    ],
                    "maxLength": 500
                  },
                  "positive_y": {
                    "type": [
                      "string",
                      "null"
                    ],
                    "maxLength": 500
                  },
                  "positive_z": {
                    "type": [
                      "string",
                      "null"
                    ],
                    "maxLength": 500
                  }
                },
                "required": [
                  "origin",
                  "positive_x",
                  "positive_y",
                  "positive_z"
                ]
              },
              "views": {
                "type": "array",
                "minItems": 1,
                "maxItems": 4,
                "uniqueItems": true,
                "items": {
                  "type": "string",
                  "enum": [
                    "front",
                    "right",
                    "top",
                    "isometric"
                  ]
                }
              },
              "unresolved": {
                "type": "array",
                "maxItems": 20,
                "items": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 2000
                }
              }
            },
            "required": [
              "deliverable",
              "requirements",
              "coordinates",
              "views",
              "unresolved"
            ],
            "description": "Transfer all relevant owner requirements, including earlier corrections. Map coordinates and requested views explicitly; keep unknown directions null. Cite exact source refs for record facts; distinguish working assumptions. The original current request and selected reference pixels are also supplied by the server."
          },
          "area_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "component_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "step_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Current work Step this drawing supports; read the plan and pass its exact ID when relevant. Null for a project-wide drawing. Planning is a phase."
          },
          "artifact_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Exact existing construction checkpoint to draw, or CAD Artifact to revise. A construction is freshly checked and rendered verbatim into a separate linked concept drawing; it is never redesigned here. Null only when no existing construction applies."
          }
        },
        "required": [
          "request_id",
          "brief",
          "handoff",
          "area_id",
          "component_id",
          "step_id",
          "artifact_id"
        ]
      },
      "handler": "design_project_cad",
      "additional_description": "Read current construction drafts and check the exact revision. Pass that construction Artifact ID as artifact_id to design_project_cad. The server rechecks its current sources and renders the same geometry with dimensions and part IDs; no second designer construction is created. Original requirements, joints, materials, checks and pixels go to the independent reviewer. Only save_cad_design saves an approved candidate; verify its receipt, exact revision, work link and readback. Correct construction issues in the checkpoint; renderer annotation defects need a renderer repair. Unknown product or strength checks remain concept limitations.",
      "required_parameters": [
        "request_id",
        "brief",
        "handoff",
        "area_id",
        "component_id",
        "step_id",
        "artifact_id"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 3,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/cad-assistant.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Collect and assess all drawing requirements, then construct and independently review CAD.",
      "description": ""
    },
    "variables": []
  },
