            "type": [
              "number",
              "null"
            ]
          },
          "placement": {
            "type": [
              "object",
              "null"
            ],
            "additionalProperties": false,
            "properties": {
              "furniture_room": {
                "type": "string",
                "enum": [
                  "left",
                  "right"
                ]
              },
              "anchor": {
                "type": "string",
                "enum": [
                  "shared_wall",
                  "outer_wall"
                ]
              },
              "gap_mm": {
                "type": "number",
                "description": "Nonnegative gap from the named wall face to the furniture footprint; not a fixing or safety assertion."
              },
              "offset_mm": {
                "type": "number",
                "description": "Nonnegative distance along the wall from the plan bottom edge to the footprint."
              },
              "rotation": {
                "type": "integer",
                "enum": [
                  0,
                  90
                ],
                "description": "0: furniture width across the room, depth along the wall. 90: swap footprint axes only, never change the construction."
