                "description": "Exact current revision read from the authorised source."
              },
              "furniture_revision": {
                "type": "integer",
                "description": "Exact current revision read from the authorised source."
              },
              "measurements": {
                "type": "array",
                "maxItems": 20,
                "description": "Exact relevant canonical measurement revisions. These are evidence, not automatic parameter bindings.",
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "required": [
                    "id",
                    "revision"
                  ],
                  "properties": {
                    "id": {
                      "type": "string",
                      "description": "Exact existing canonical UUID from current project research. Never invent an identity."
                    },
                    "revision": {
                      "type": "integer",
                      "description": "Exact current revision read from the authorised source."
                    }
                  }
                }
              }
            },
            "required": [
