      "handler": "ensure_drawing_gap_task",
      "additional_description": "Read stable request/gap IDs and the current Plan revision first. The gap must reference an already shared canonical requirement. Reuses the requirement Task atomically across repeated calls and requests; never copies private collector text.",
      "required_parameters": [
        "request_id",
        "expected_revision",
        "gap_id",
        "requirement_id",
        "plan_revision"
      ],
