  {
    "key": "tools.inspect_building_projection",
    "kind": "tool_contract",
    "label": "Inspect what mapped rooms lie vertically above or below a rectangular area in a saved multi-floor plan. Read-only; this is not a stair calculation.",
    "description": "",
    "content": "",
    "definition": {
      "name": "inspect_building_projection",
      "description": "Read-only coordinate calculation on an exact CURRENT saved multi-floor plan. Resolve the artifact and level IDs first. Project a rectangle at the same building x/y onto another floor; returns intersected mapped room footprints and known floor/slab elevations. Consumes one project lookup, never saves changes. Does not calculate a staircase, path, headroom or safe opening. A missing mapped room is unknown coverage, not evidence of an empty room. Report stale sources and estimates.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "record_id": {
            "type": "string",
            "description": "Exact canonical UUID from fresh project research. Never invent one."
          },
          "expected_revision": {
            "type": "integer",
            "minimum": 1
          },
          "from_level_id": {
            "type": "string",
            "description": "Exact canonical UUID from fresh project research. Never invent one."
          },
          "to_level_id": {
            "type": "string",
            "description": "Exact canonical UUID from fresh project research. Never invent one."
          },
          "bounds": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "x_mm": {
                "type": "number"
              },
              "y_mm": {
                "type": "number"
              },
              "width_mm": {
                "type": "number"
              },
              "depth_mm": {
                "type": "number"
              }
            },
            "required": [
              "x_mm",
              "y_mm",
              "width_mm",
              "depth_mm"
            ]
          }
        },
        "required": [
          "record_id",
          "expected_revision",
          "from_level_id",
          "to_level_id",
          "bounds"
        ]
      },
      "handler": "inspect_building_projection",
      "additional_description": "Read the current exact source plan first. Projection preserves x/y; show full containment, partial overlap, envelope conflicts and unknown coverage. Empty mapped hits do not mean empty physical space. Floor/slab differences require known heights. For a staircase use an actual stair generator and disclose its shape limits.",
      "required_parameters": [
        "record_id",
        "expected_revision",
        "from_level_id",
        "to_level_id",
        "bounds"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/project-building-plan.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Inspect what mapped rooms lie vertically above or below a rectangular area in a saved multi-floor plan. Read-only; this is not a stair calculation.",
      "description": ""
    },
    "variables": []
  },
  {
    "key": "tools.inspect_stair_options",
    "kind": "tool_contract",
    "label": "Compare straight or quarter-turn stairs with a square landing on a saved multi-floor plan. Read-only geometric study; not a rounded/winder stair generator.",
    "description": "",
    "content": "",
    "definition": {
      "name": "inspect_stair_options",
      "description": "READ ONLY: calculate 1–4 candidate stairs on an exact current multi-floor plan. Reads the plan with current caller access (one lookup), then derives treads, turning landing, upper exit coordinates/direction and room overlaps. Reports modelled envelope/opening/headroom conflicts, missing inputs and a conservative opening rectangle. Supports straight or quarter-turn WITH SQUARE LANDING, not rounded winders/spirals. Never call a projection a stair solution. Passing these limited checks is not proof of doors, circulation, structure, safety or building approval. Recommend only by the returned evidence and stated user goals. No save or physical mutation.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "plan_id": {
            "type": "string"
          },
          "plan_revision": {
            "type": "integer",
            "minimum": 1
          },
          "candidates": {
            "type": "array",
            "minItems": 1,
            "maxItems": 4,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "label": {
                  "type": "string"
                },
                "recipe": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "generator": {
                      "type": "string",
                      "enum": [
                        "stair_study_v1"
                      ]
                    },
                    "version": {
                      "type": "integer",
                      "enum": [
                        1
                      ]
                    },
                    "from_level_id": {
                      "type": "string"
                    },
                    "to_level_id": {
                      "type": "string"
                    },
                    "start_x_mm": {
                      "type": "number",
                      "description": "Centre of first riser, at lower floor; shared building x/east datum."
                    },
                    "start_y_mm": {
                      "type": "number",
                      "description": "Centre of first riser, shared building y/north datum."
                    },
                    "heading": {
                      "type": "string",
                      "enum": [
                        "north",
                        "east",
                        "south",
                        "west"
                      ]
                    },
                    "turn": {
                      "type": "string",
                      "enum": [
                        "straight",
                        "left",
                        "right"
                      ]
                    },
                    "risers": {
                      "type": "integer",
                      "minimum": 3,
                      "maximum": 60
                    },
                    "first_flight_risers": {
                      "type": [
                        "integer",
                        "null"
                      ],
                      "description": "Rises to square intermediate landing for a quarter turn; 2 through total-2. Null for straight."
                    },
                    "width_mm": {
                      "type": "integer",
                      "description": "Walking strip width, whole mm; no stringers/handrails added."
                    },
                    "going_mm": {
                      "type": "integer"
                    },
                    "landing_depth_mm": {
                      "type": "integer"
                    },
                    "opening": {
                      "type": [
                        "object",
                        "null"
                      ],
                      "additionalProperties": false,
                      "properties": {
                        "x_mm": {
                          "type": "number"
                        },
                        "y_mm": {
                          "type": "number"
                        },
                        "width_mm": {
                          "type": "number"
                        },
                        "depth_mm": {
                          "type": "number"
                        }
                      },
                      "required": [
                        "x_mm",
                        "y_mm",
                        "width_mm",
                        "depth_mm"
                      ],
                      "description": "Explicit rectangular floor-opening proposal. Null means unspecified, not a solid/empty floor. Inspect first for a conservative suggestion; do not remove slabs."
                    },
                    "required_headroom_mm": {
                      "type": "integer",
                      "description": "Explicit project study criterion, not an automatically determined legal standard."
                    },
                    "upper_ceiling_above_floor_mm": {
                      "type": [
                        "integer",
                        "null"
                      ],
                      "description": "Flat upper ceiling height above upper finished floor. Null if unknown; never infer it from slab thickness."
                    },
                    "basis": {
                      "type": "string",
                      "enum": [
                        "provided_spec",
                        "estimated"
                      ]
                    },
                    "source": {
                      "type": "string",
                      "description": "Identify actual supplied dimensions or explicit reversible design assumptions."
                    }
                  },
                  "required": [
                    "generator",
                    "version",
                    "from_level_id",
                    "to_level_id",
                    "start_x_mm",
                    "start_y_mm",
                    "heading",
                    "turn",
                    "risers",
                    "first_flight_risers",
                    "width_mm",
                    "going_mm",
                    "landing_depth_mm",
                    "opening",
                    "required_headroom_mm",
                    "upper_ceiling_above_floor_mm",
                    "basis",
                    "source"
                  ]
                }
              },
              "required": [
                "label",
                "recipe"
              ]
            }
          }
        },
        "required": [
          "plan_id",
          "plan_revision",
          "candidates"
        ]
      },
      "handler": "inspect_stair_options",
      "additional_description": "Read current plan sources first. Compare one to four explicit parameter candidates; use returned exit, direction and headroom facts. Choose reversible design assumptions, but do not invent unknown floor or ceiling heights. Headroom is a stated study criterion, not a verified regulation. Checks cover full walking rectangles against a flat slab and rectangular opening; doors, beams, roof slopes, structure and safety remain unmodelled.",
      "required_parameters": [
        "plan_id",
        "plan_revision",
        "candidates"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/project-stair.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Compare straight or quarter-turn stairs with a square landing on a saved multi-floor plan. Read-only geometric study; not a rounded/winder stair generator.",
      "description": ""
    },
    "variables": []
  },
  {
    "key": "tools.link_cad_shell_steps",
    "kind": "tool_contract",
    "label": "Link the pieces of a shell drawing to current plan Steps in one go, or unlink them.",
    "description": "",
    "content": "",
    "definition": {
      "name": "link_cad_shell_steps",
      "description": "Link the pieces of a shell drawing to current plan Steps in one go, or unlink them. Each link is held by the piece, exactly as link_project_drawing would save it; the shell itself is not changed.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "shell_id",
          "expected_revision",
          "links",
          "request_quote"
        ],
        "properties": {
          "shell_id": {
            "type": "string",
            "description": "Shell drawing id from read_cad_shell or its save receipt."
          },
          "expected_revision": {
            "type": "integer",
            "minimum": 1,
            "description": "The shell revision you last read."
          },
          "links": {
            "type": "array",
            "minItems": 1,
            "maxItems": 64,
            "description": "One entry per piece and Step, in build order.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "component_key",
                "step_id",
                "action"
              ],
              "properties": {
                "component_key": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9_-]{0,39}$",
                  "description": "Exactly as read_cad_shell returns it."
                },
                "step_id": {
                  "type": "string",
                  "description": "Exact current plan Step id."
                },
                "action": {
                  "type": "string",
                  "enum": [
                    "link",
                    "unlink"
                  ]
                }
              }
            }
          },
          "request_quote": {
            "type": "string",
            "description": "Exact quote from the CURRENT user message authorising this change."
          }
        }
      },
      "handler": "link_cad_shell_steps",
      "additional_description": "Read the shell with read_cad_shell and the current plan first. Each link names a component_key from the shell and an exact current Step id; the link is held by the piece, as link_project_drawing would. Use the shell revision as expected_revision. Link each piece to the Step that builds it, in build order (for example walls before the bed that stands against them). When a piece has no fitting Step, add the Step with edit_project_plan first, then link. One piece can serve several Steps.",
      "required_parameters": [
        "shell_id",
        "expected_revision",
        "links",
        "request_quote"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/project-write.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Link the pieces of a shell drawing to current plan Steps in one go, or unlink them.",
      "description": "",
      "server_fields": [
        "request_quote"
      ]
    },
    "variables": []
  },
  {
    "key": "tools.link_drawing_gap",
    "kind": "tool_contract",
    "label": "Link a drawing gap to existing project work.",
    "description": "",
    "content": "",
    "definition": {
      "name": "link_drawing_gap",
      "description": "Link a stable drawing gap to an existing project Task and/or Step. Read request work first and reuse existing links; never duplicate a Task by its title. Do not copy private assessment prose into project Tasks. Null references leave the gap as a chat complement.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "request_id": {
            "type": "string"
          },
          "expected_revision": {
            "type": "integer",
            "minimum": 0
          },
          "gap_id": {
