  {
    "key": "tools.plan_cad_pieces",
    "kind": "tool_contract",
    "label": "Split a large build into separately designed and saved drawing pieces.",
    "description": "",
    "content": "",
    "definition": {
      "name": "plan_cad_pieces",
      "description": "Split one large build (a room, extension, house, or anything with more than about 24 parts or several structural systems) into 2-12 pieces that are each designed and saved as their own drawing. Pieces are queued and designed one at a time after this reply; each saved piece appears in this conversation. A failed piece does not stop the others and can be resumed by its request_id with design_project_cad. Give every piece a complete standalone brief and handoff in the same shared coordinate system (state the origin and axes once in assembly_brief and repeat them in each handoff). For a single small object use design_project_cad instead.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "assembly_title",
          "assembly_brief",
          "area_id",
          "pieces"
        ],
        "properties": {
          "assembly_title": {
            "type": "string",
            "maxLength": 200
          },
          "assembly_brief": {
            "type": "string",
            "maxLength": 3000,
            "description": "Whole-build intent, shared origin/axes and how the pieces meet."
          },
          "area_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "pieces": {
            "type": "array",
            "minItems": 2,
            "maxItems": 12,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "piece_key",
                "brief",
                "component_id",
                "handoff"
              ],
              "properties": {
                "piece_key": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9_-]{0,39}$",
                  "description": "Stable short key, e.g. wall_north, floor, roof, bunk_bed."
                },
                "brief": {
                  "type": "string",
                  "maxLength": 5000
                },
                "component_id": {
                  "type": [
                    "string",
                    "null"
                  ]
                },
                "handoff": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "deliverable": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 2000
                    },
                    "requirements": {
                      "type": "array",
                      "minItems": 1,
                      "maxItems": 24,
                      "items": {
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                          "id": {
                            "type": "string",
                            "pattern": "^[a-zA-Z0-9_-]{1,40}$"
                          },
                          "requirement": {
                            "type": "string",
                            "minLength": 1,
                            "maxLength": 2000
                          },
                          "basis": {
                            "type": "string",
                            "enum": [
                              "user_request",
                              "project_record",
                              "working_assumption"
                            ]
                          },
                          "source_ref": {
                            "type": [
                              "string",
                              "null"
                            ],
                            "maxLength": 500
                          }
                        },
                        "required": [
                          "id",
                          "requirement",
                          "basis",
                          "source_ref"
                        ]
                      }
                    },
                    "coordinates": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "origin": {
                          "type": [
                            "string",
                            "null"
                          ],
                          "maxLength": 500
                        },
                        "positive_x": {
                          "type": [
                            "string",
                            "null"
                          ],
                          "maxLength": 500
                        },
                        "positive_y": {
                          "type": [
                            "string",
                            "null"
                          ],
                          "maxLength": 500
                        },
                        "positive_z": {
                          "type": [
                            "string",
                            "null"
                          ],
                          "maxLength": 500
                        }
                      },
                      "required": [
                        "origin",
                        "positive_x",
                        "positive_y",
                        "positive_z"
                      ]
                    },
                    "views": {
                      "type": "array",
                      "minItems": 1,
                      "maxItems": 4,
                      "uniqueItems": true,
                      "items": {
                        "type": "string",
                        "enum": [
                          "front",
                          "right",
                          "top",
                          "isometric"
                        ]
                      }
                    },
                    "unresolved": {
                      "type": "array",
                      "maxItems": 20,
                      "items": {
                        "type": "string",
                        "minLength": 1,
                        "maxLength": 2000
                      }
                    }
                  },
                  "required": [
                    "deliverable",
                    "requirements",
                    "coordinates",
                    "views",
                    "unresolved"
                  ]
                }
              }
            }
          }
        }
      },
      "handler": "plan_cad_pieces",
      "additional_description": "Use instead of design_project_cad when one drawing would need more than about 24 parts or several structural systems (walls, floor, roof, stairs, built-in furniture). Give 2-12 pieces, each with a complete standalone brief and handoff in one shared coordinate system. Pieces are designed one at a time after your reply while the owner has Bob open; each saved piece appears in the conversation. Tell the owner the pieces and that they arrive one by one. A failed piece can be resumed alone by its request_id. Saved pieces are concepts, not measured truth or structural approval.",
      "required_parameters": [
        "assembly_title",
        "assembly_brief",
        "area_id",
        "pieces"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/cad-pieces.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Split a large build into separately designed and saved drawing pieces.",
      "description": ""
    },
    "variables": []
  },
  {
    "key": "tools.propose_project_plan",
    "kind": "tool_contract",
    "label": "Create a reviewable living Project Plan proposal with dynamic Steps, Completion Requirements, responsibility and evidence selectors. It is not current until explicitly approved.",
    "description": "",
    "content": "",
    "definition": {
      "name": "propose_project_plan",
      "description": "Create a reviewable plan of work Steps. Task ownership links are staged with it and applied atomically on approval. Completed Steps retain their history. Independent Steps may be active together; Bob focus is separate.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "expected_revision": {
            "type": "integer",
            "description": "Current approved living-plan revision, or 0 when none exists."
          },
          "summary": {
            "type": "string",
            "description": "Compact description of the proposed working plan."
          },
          "reason": {
            "type": "string",
            "description": "Why this plan or replan is appropriate now, including material new evidence."
          },
          "steps": {
            "type": "array",
            "maxItems": 100,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "step_id": {
                  "type": [
                    "string",
                    "null"
                  ],
                  "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$",
                  "description": "Stable UUID from current plan when this is the same active/future Step; null for a new Step."
                },
                "title": {
                  "type": "string"
                },
                "goal": {
                  "type": "string"
                },
                "state": {
                  "type": "string",
                  "enum": [
                    "planned",
                    "active",
                    "blocked",
                    "completed"
                  ]
                },
                "area_id": {
                  "type": [
                    "string",
                    "null"
                  ],
                  "description": "Optional organisational Area. Null places the Step directly in the Project."
                },
                "phase": {
                  "type": [
                    "string",
                    "null"
                  ],
                  "enum": [
                    "concept",
                    "design",
                    "planning",
                    "build",
                    "complete",
                    null
                  ]
                },
                "responsible_kind": {
                  "type": "string",
                  "enum": [
                    "bob",
                    "person",
                    "unassigned"
                  ],
                  "description": "Who owns the work, not who is authorized to approve it. person uses an exact project person ID."
                },
                "responsible_person_id": {
                  "type": [
                    "string",
                    "null"
                  ],
                  "description": "Exact bob.people ID when responsible_kind=person; otherwise null."
                },
                "notes": {
                  "type": "string",
                  "description": "Step Brief: Bob's concise self-prompt for this Step — purpose, focus, important constraints and what matters while working here. Keep it compact; project facts and Completion Requirements remain authoritative."
                },
                "requirements": {
                  "type": "array",
                  "maxItems": 20,
                  "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "requirement_id": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$",
                        "description": "Exact Requirement UUID from the current plan, never a Task ID; null for a new requirement."
                      },
                      "type": {
                        "type": "string",
                        "enum": [
                          "measurement",
                          "photo",
                          "decision",
                          "drawing",
                          "material_requirement",
                          "material_delivery",
                          "task",
                          "approval",
                          "check",
                          "other"
                        ]
                      },
                      "title": {
                        "type": "string"
                      },
                      "description": {
                        "type": "string"
                      },
                      "resolution": {
                        "type": "string",
                        "enum": [
                          "open",
                          "waived",
                          "not_applicable"
                        ]
                      },
                      "responsible_kind": {
                        "type": "string",
                        "enum": [
                          "bob",
                          "person",
                          "unassigned"
                        ],
                        "description": "Who owns the work, not who is authorized to approve it. person uses an exact project person ID."
                      },
                      "responsible_person_id": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "description": "Exact bob.people ID when responsible_kind=person; otherwise null."
                      },
                      "evidence_selector": {
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                          "kind": {
                            "type": "string",
                            "enum": [
                              "none",
                              "measurement",
                              "media",
                              "artifact",
                              "material_requirement",
                              "solution",
                              "task"
                            ]
                          },
                          "id": {
                            "type": [
                              "string",
                              "null"
                            ]
                          },
                          "subject": {
                            "type": [
                              "string",
                              "null"
                            ]
                          },
                          "area_id": {
                            "type": [
                              "string",
                              "null"
                            ]
                          }
                        },
                        "required": [
                          "kind",
                          "id",
                          "subject",
                          "area_id"
                        ],
                        "description": "Optional dynamic evidence selector. measurement may use exact measurement id, or exact subject plus optional Area. Other kinds require exact id. none has all nullable fields null."
                      }
                    },
                    "required": [
                      "requirement_id",
                      "type",
                      "title",
                      "description",
                      "resolution",
                      "responsible_kind",
                      "responsible_person_id",
                      "evidence_selector"
                    ]
                  }
                }
              },
              "required": [
                "step_id",
                "title",
                "goal",
                "state",
                "area_id",
                "responsible_kind",
                "responsible_person_id",
                "notes",
                "requirements",
                "phase"
              ]
            }
          },
          "task_links": {
            "type": "array",
            "maxItems": 200,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "step_position": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 100
                },
                "task_id": {
                  "type": "string"
                }
              },
              "required": [
                "step_position",
                "task_id"
              ]
            },
            "description": "Primary ownership of existing Tasks by 1-based submitted Step position. Each Task occurs once. Empty preserves existing ownership."
          },
          "request_quote": {
            "type": "string",
            "description": "Exact quote from the CURRENT user request authorising planning/replanning."
          }
        },
        "required": [
          "expected_revision",
          "summary",
          "reason",
          "steps",
          "task_links",
          "request_quote"
        ]
      },
      "handler": "propose_project_plan",
      "additional_description": "Low-level manual proposal write. Normally do NOT use this after compile_project_plan: save_compiled_project_plan owns that path and preserves the exact reviewed compilation. Use this only when a manual proposal genuinely cannot come from the compiler. It still requires the exact current revision and the full strict Step/Requirement schema.",
      "required_parameters": [
        "expected_revision",
        "summary",
        "reason",
        "steps",
        "task_links",
        "request_quote"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/project-write.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Create a reviewable living Project Plan proposal with dynamic Steps, Completion Requirements, responsibility and evidence selectors. It is not current until explicitly approved.",
      "description": "",
      "server_fields": [
        "request_quote"
      ]
    },
    "variables": []
  },
