                        "material_ref",
                        "primitive",
                        "outside_diameter_mm",
                        "wall_thickness_mm",
                        "length_mm"
                      ]
                    }
                  ]
                }
              },
              "instances": {
                "type": "array",
                "minItems": 0,
                "maxItems": 512,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "definition_id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "placement": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "x": {
                          "type": "number",
                          "maximum": 10000000,
                          "minimum": -10000000
                        },
                        "y": {
                          "type": "number",
                          "maximum": 10000000,
                          "minimum": -10000000
                        },
                        "z": {
                          "type": "number",
                          "maximum": 10000000,
                          "minimum": -10000000
                        },
                        "rx": {
                          "type": "number",
                          "maximum": 360000,
                          "minimum": -360000
                        },
                        "ry": {
                          "type": "number",
                          "maximum": 360000,
                          "minimum": -360000
                        },
                        "rz": {
                          "type": "number",
                          "maximum": 360000,
                          "minimum": -360000
                        }
                      },
                      "required": [
                        "x",
                        "y",
                        "z",
                        "rx",
                        "ry",
                        "rz"
                      ]
                    }
                  },
                  "required": [
                    "id",
                    "definition_id",
                    "placement"
                  ]
                }
              },
              "views": {
                "type": "array",
                "minItems": 1,
                "maxItems": 4,
                "items": {
                  "type": "string",
                  "enum": [
                    "front",
                    "right",
                    "top",
                    "isometric"
                  ]
                }
              },
              "clearances": {
                "type": "array",
                "maxItems": 16,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "first_id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "second_id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "min_mm": {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 1000000
                    }
                  },
                  "required": [
                    "id",
                    "first_id",
                    "second_id",
                    "min_mm"
                  ]
                }
              },
              "motions": {
                "type": "array",
                "maxItems": 16,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "moving_ids": {
                      "type": "array",
                      "minItems": 1,
                      "maxItems": 8,
                      "items": {
                        "type": "string",
                        "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                      }
                    },
                    "obstacle_ids": {
                      "type": "array",
                      "minItems": 1,
                      "maxItems": 32,
                      "items": {
                        "type": "string",
                        "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                      }
                    },
                    "delta": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "x": {
                          "type": "number",
                          "maximum": 1000000,
                          "minimum": -1000000
                        },
                        "y": {
                          "type": "number",
                          "maximum": 1000000,
                          "minimum": -1000000
                        },
