                    "moving_ids",
                    "obstacle_ids",
                    "delta"
                  ]
                }
              },
              "arrays": {
                "type": "array",
                "maxItems": 64,
                "description": "Repeat templates for evenly spaced identical parts (studs, slats, joists, rungs). Each expands to instances <id>.1..<id>.<count>. Bind arrays/<id>/start/x|y|z|rx|ry|rz (first copy) and arrays/<id>/spacing_mm (centre-to-centre step along axis); do not bind the expanded instances. Copy N sits at start + (N-1) x spacing along axis.",
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "required": [
                    "id",
                    "definition_id",
                    "axis",
                    "count"
                  ],
                  "properties": {
