                              "type": "string",
                              "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                            },
                            "y": {
                              "type": "string",
                              "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                            },
                            "z": {
                              "type": "string",
                              "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                            },
                            "rx": {
                              "type": "string",
                              "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                            },
                            "ry": {
                              "type": "string",
                              "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                            },
                            "rz": {
                              "type": "string",
                              "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                            }
                          },
                          "required": [
                            "x",
                            "y",
                            "z",
                            "rx",
                            "ry",
                            "rz"
                          ]
                        },
                        {
                          "type": "null"
                        }
                      ]
                    }
                  },
                  "required": [
                    "id",
                    "kind",
                    "source_ref",
                    "required",
                    "reason",
                    "placement"
                  ]
                }
