  {
    "key": "tools.save_building_context",
    "kind": "tool_contract",
    "label": "Record a narrated house as linked Building, Level, Space and element observations or proposals. This records context; it does not calculate a drawing.",
    "description": "",
    "content": "",
    "definition": {
      "name": "save_building_context",
      "description": "Record the user-described Building, levels, spaces/zones, elements, relationships and room measurement references in one atomic batch, reusing the canonical model. Read physical_buildings/levels/spaces/elements/relationships first and reuse identities. New building_id=null creates AND links a NEW building to this project; never link an existing unscoped building implicitly. Existing facts require Building edit authority. Project-only members can propose space/element/relationship changes, not change accepted reality or create levels. Distinguish zones from walls, adjacency from a walkable connection, above from an identical footprint, and estimates from measurements. No coordinates, staircase calculation or safety approval is provided. Capture narration only when the user requests saving; examples and hypothetical questions are not permission. Source quotes must be actual user messages, not model answers or summaries.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "building_id",
          "expected_building_revision",
          "new_building_name",
          "new_building_notes",
          "operations",
          "request_quote"
        ],
        "properties": {
          "building_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Exact project-scoped Building UUID, or null only for an explicitly requested NEW building."
          },
          "expected_building_revision": {
            "type": "integer",
            "description": "Current Building metadata revision, or 0 for new."
          },
          "new_building_name": {
            "type": [
              "string",
              "null"
            ],
            "description": "Required for new Building; null for existing."
          },
          "new_building_notes": {
            "type": [
              "string",
              "null"
            ],
            "description": "For new Building only: actual described orientation/extent, source and uncertainty; no invented measured geometry. Null for existing."
          },
          "operations": {
            "type": "array",
            "minItems": 1,
            "maxItems": 40,
            "description": "Dependency ordered: measurements/levels, then spaces, then elements/relationships. One edit per identity. Report incomplete capture when a story needs more than one batch.",
            "items": {
              "anyOf": [
                {
                  "type": "object",
                  "additionalProperties": false,
                  "required": [
                    "key",
                    "kind",
                    "record_id",
                    "expected_revision",
                    "mode",
                    "source_quote",
                    "source_seq",
                    "fields"
                  ],
                  "properties": {
                    "key": {
                      "type": "string",
                      "description": "Unique lowercase key, letters/digits/underscores, start with letter, max 40."
                    },
                    "kind": {
                      "type": "string",
                      "enum": [
                        "building"
                      ]
                    },
                    "record_id": {
                      "type": [
                        "string",
                        "null"
                      ]
                    },
                    "expected_revision": {
                      "type": "integer",
                      "description": "0=create, exact current latest revision=update. Never implicitly accept a pending proposal."
                    },
                    "mode": {
                      "type": "string",
                      "enum": [
                        "existing",
                        "proposed"
                      ],
                      "description": "existing=user-described current reality; proposed=remodel idea (ai_assessment). Building/levels/measurements use existing."
                    },
                    "source_quote": {
                      "type": "string",
                      "description": "Exact 1–500 character USER quote supporting this operation."
                    },
                    "source_seq": {
                      "type": [
                        "integer",
                        "null"
                      ],
                      "description": "null=current user message; otherwise exact earlier USER seq from same-conversation history research."
                    },
                    "fields": {
                      "type": "object",
                      "additionalProperties": false,
                      "minProperties": 1,
                      "properties": {
                        "notes_append": {
                          "type": "string",
                          "description": "Append user-described facts to the existing Building notes, never replace unrelated context. Max 2000 characters; total canonical notes remain bounded."
                        }
                      },
                      "description": "PATCH on update: omit unchanged fields. Building operations only append notes to the already identified root. Create needs name, or measurement subject/value/unit/truth, or both relationship endpoints/relation. Sources and audit are server-owned."
                    }
                  }
                },
                {
                  "type": "object",
