  {
    "key": "tools.save_construction_cut_plan",
    "kind": "tool_contract",
    "label": "Save a checked sheet-cutting layout under the existing exact blank needs.",
    "description": "",
    "content": "",
    "definition": {
      "name": "save_construction_cut_plan",
      "description": "Save a feasible sheet cutting plan under ALL existing piece needs from this exact current construction. Code computes the layout and SQL independently replays the cuts; never supply placements or claim that an area sum proves fit. Read existing cut_plan and requirement resources first. Reuse record_id/current revision when updating; key names one intended write in the turn. candidate_sources names every candidate: hypothetical uses null record_id/revision; stock pins an existing current stock revision with sheet_format and available whole sheets; catalog_part pins a current panel part with exact material and dimensions, not a verified supplier/product. Preserve hypothetical/estimated evidence. This saves a plan only: no stock reservation, Shopping handoff, optimal purchase count or fabrication approval. Read_project_work(cut_plan) to reopen the receipt and inspect source_state.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "key": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_-]{1,80}$"
          },
          "record_id": {
            "anyOf": [
              {
                "type": "string",
                "format": "uuid"
              },
              {
                "type": "null"
              }
            ]
          },
          "expected_revision": {
            "type": "integer",
            "minimum": 0,
            "maximum": 999999999
          },
          "artifact_id": {
            "type": "string",
            "format": "uuid"
          },
          "revision": {
            "type": "integer",
            "minimum": 1,
            "maximum": 999999999
          },
          "candidates": {
            "type": "array",
            "minItems": 1,
            "maxItems": 8,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "id": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                },
                "material_id": {
                  "type": "string",
                  "format": "uuid"
                },
                "material_revision": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 999999999
                },
                "length_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0.000001,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "width_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0.000001,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "thickness_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0.000001,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "count": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 16
                },
                "kerf_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "trim_mm": {
                  "anyOf": [
                    {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 1000000
                    },
                    {
                      "type": "null"
