      "handler": "save_construction_cut_plan",
      "additional_description": "Read current construction and all saved piece requirements first. Supply candidate formats, exact material/need pins, kerf/trim, grain and candidate_sources. The handler computes placements/cuts; SQL independently replays them. Reuse an existing cut-plan identity on revision. Hypothetical formats remain hypothetical; stock sources require matching current structured sheet_format and unreserved whole-piece capacity. Catalog panel parts pin format, not supplier/product approval. Read_project_work(cut_plan) reopens the saved result and source_state. This save does not reserve stock, publish Shopping or approve fabrication.",
      "required_parameters": [
        "key",
        "record_id",
        "expected_revision",
        "artifact_id",
        "revision",
        "candidates",
        "blank_grain",
        "requirements",
        "candidate_sources",
        "change_note",
        "request_quote"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
