            "type": "array",
            "minItems": 1,
            "maxItems": 128,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "definition_id": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                },
                "material_id": {
                  "type": "string",
                  "format": "uuid"
                },
                "material_revision": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 999999999
                },
                "part_id": {
                  "anyOf": [
                    {
                      "type": "string",
                      "format": "uuid"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "part_revision": {
                  "anyOf": [
                    {
                      "type": "integer",
