                  ]
                },
                "first": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "instance_id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
