                        "x_min",
                        "x_max",
                        "y_min",
                        "y_max",
                        "z_min",
                        "z_max"
                      ]
                    }
                  },
                  "required": [
                    "instance_id",
                    "face"
                  ]
                },
                "second": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "instance_id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "face": {
                      "type": "string",
                      "enum": [
                        "x_min",
                        "x_max",
                        "y_min",
                        "y_max",
                        "z_min",
                        "z_max"
                      ]
                    }
                  },
                  "required": [
                    "instance_id",
                    "face"
                  ]
                },
                "reason": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 2000
                }
              },
              "required": [
                "id",
                "method",
                "first",
                "second",
                "reason"
              ]
            }
          },
          "open_questions": {
            "type": "array",
            "maxItems": 40,
            "items": {
              "type": "string",
              "minLength": 1,
              "maxLength": 1000
            }
          },
          "request_quote": {
            "type": "string",
            "minLength": 1,
            "maxLength": 500
          }
        },
        "required": [
          "key",
          "record_id",
          "expected_revision",
          "title",
          "description",
          "area_id",
          "target_revision",
          "change_note",
          "recipe",
          "parameter_plan",
          "materials",
          "joints",
          "open_questions",
          "request_quote"
        ]
      },
      "handler": "save_construction_draft",
      "additional_description": "Read existing drafts and catalog revisions first. Reuse Artifact, assembly, part and joint IDs. Supply the complete CAD parameter plan; the server calculates values and rejects unknown controlling dimensions. Joint methods are design choices, not checked strength or hardware. Open questions stay explicit. A draft receipt is not a drawing or purchase receipt. For a delegated assembly choose the parts and joints from the request, exact catalog and applicable building knowledge; ordinary reversible choices are design_choice, not new owner approvals. Derive dependent spans and positions from shared dimension nodes. After saving, call check_construction_draft on that revision and correct reported IDs with another revision. Compare bounds/count against the original requirements. A checked concept is not fabrication approval. For a requested drawing pass this checked construction Artifact ID to design_project_cad. A construction receipt alone is not a drawing delivery; verify the drawing save/link receipts and exact readback.",
      "required_parameters": [
        "key",
        "record_id",
        "expected_revision",
        "title",
        "description",
        "area_id",
        "target_revision",
        "change_note",
        "recipe",
        "parameter_plan",
        "materials",
        "joints",
        "open_questions",
        "request_quote"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/construction-draft.ts",
