  {
    "key": "tools.save_project_building_plan",
    "kind": "tool_contract",
    "label": "Create or revise a multi-floor coordinate study using existing Building/Level/Space identities, explicit room bounds and floor heights.",
    "description": "",
    "content": "",
    "definition": {
      "name": "save_project_building_plan",
      "description": "Create/revise a bounded multi-floor coordinate study in Bob, using existing canonical Building/Level/Space IDs and selected target. Read current sources and the current artifact first. East is +x, north is +y, up is +z; all floors share one explicit datum. Numeric envelopes are outside bounds; room bounds are inside footprints, not inferred walls or doors. Unknown room bounds and floor heights remain null. A projected study area is NOT a generated staircase or floor opening. Save all plan views atomically as Concept. Normal revise preserves source identities/revisions and evidence. refresh_sources adopts current source revisions without changing coordinates. Keep unrelated data; no physical-state acceptance or safety/readiness claims.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "record_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "action": {
            "type": "string",
            "enum": [
              "create",
              "revise",
              "refresh_sources"
            ]
          },
          "expected_revision": {
            "type": "integer"
          },
          "create_area_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "target_revision": {
            "type": "integer",
            "minimum": 1
          },
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "assumptions": {
            "type": "string"
          },
          "recipe": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "generator": {
                "type": "string",
                "enum": [
                  "multifloor_v1"
                ]
              },
              "version": {
                "type": "integer",
                "enum": [
                  1
                ]
              },
              "building_id": {
                "type": "string",
                "description": "Exact canonical UUID from fresh project research. Never invent one."
              },
              "building_revision": {
                "type": "integer",
                "minimum": 1
              },
              "frame": {
                "type": "string",
                "enum": [
                  "east_north_up"
                ]
              },
              "origin": {
                "type": "string",
                "description": "Explicit shared physical or assumed origin for x/y/z. Identify assumptions. Both levels use it, not independent room origins."
              },
              "levels": {
                "type": "array",
                "minItems": 2,
                "maxItems": 6,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "level_id": {
                      "type": "string",
                      "description": "Exact canonical UUID from fresh project research. Never invent one."
                    },
                    "level_revision": {
                      "type": "integer",
                      "minimum": 1
                    },
                    "bounds": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "x_mm": {
                          "type": "number"
                        },
                        "y_mm": {
                          "type": "number"
                        },
                        "width_mm": {
                          "type": "number"
                        },
                        "depth_mm": {
                          "type": "number"
                        }
                      },
                      "required": [
                        "x_mm",
                        "y_mm",
                        "width_mm",
                        "depth_mm"
                      ]
                    },
                    "wall_mm": {
                      "type": "number"
                    },
                    "floor_z_mm": {
                      "type": [
                        "number",
                        "null"
                      ],
                      "description": "Finished-floor elevation from the SAME building datum, in mm. Unknown is null. Never infer from level order."
                    },
                    "slab_mm": {
                      "type": [
                        "number",
                        "null"
                      ],
                      "description": "Thickness below this level finished floor to the slab underside. Unknown is null."
                    },
                    "basis": {
                      "type": "string",
                      "enum": [
                        "provided_spec",
                        "estimated"
                      ]
                    },
                    "source": {
                      "type": "string",
                      "maxLength": 500
                    }
                  },
                  "required": [
                    "level_id",
                    "level_revision",
                    "bounds",
                    "wall_mm",
                    "floor_z_mm",
                    "slab_mm",
                    "basis",
                    "source"
                  ]
                }
              },
              "spaces": {
                "type": "array",
                "maxItems": 32,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "space_id": {
                      "type": "string",
                      "description": "Exact canonical UUID from fresh project research. Never invent one."
                    },
                    "space_revision": {
                      "type": "integer",
                      "minimum": 1
                    },
                    "level_id": {
                      "type": "string",
                      "description": "Exact canonical UUID from fresh project research. Never invent one."
                    },
                    "bounds": {
                      "type": [
                        "object",
                        "null"
                      ],
                      "additionalProperties": false,
                      "properties": {
                        "x_mm": {
                          "type": "number"
                        },
                        "y_mm": {
                          "type": "number"
                        },
                        "width_mm": {
                          "type": "number"
                        },
                        "depth_mm": {
                          "type": "number"
                        }
                      },
                      "required": [
                        "x_mm",
                        "y_mm",
                        "width_mm",
                        "depth_mm"
                      ]
                    },
                    "basis": {
                      "type": "string",
                      "enum": [
                        "provided_spec",
                        "estimated"
                      ]
                    },
                    "source": {
                      "type": "string",
                      "maxLength": 500
                    }
                  },
                  "required": [
                    "space_id",
                    "space_revision",
                    "level_id",
                    "bounds",
                    "basis",
                    "source"
                  ]
                }
              },
              "probes": {
                "type": "array",
                "maxItems": 4,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "key": {
                      "type": "string"
                    },
                    "label": {
                      "type": "string"
                    },
                    "from_level_id": {
                      "type": "string",
                      "description": "Exact canonical UUID from fresh project research. Never invent one."
                    },
                    "to_level_id": {
                      "type": "string",
                      "description": "Exact canonical UUID from fresh project research. Never invent one."
                    },
                    "bounds": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "x_mm": {
                          "type": "number"
                        },
                        "y_mm": {
                          "type": "number"
                        },
                        "width_mm": {
                          "type": "number"
                        },
                        "depth_mm": {
                          "type": "number"
                        }
                      },
                      "required": [
                        "x_mm",
                        "y_mm",
                        "width_mm",
                        "depth_mm"
                      ]
                    }
                  },
                  "required": [
                    "key",
                    "label",
                    "from_level_id",
                    "to_level_id",
                    "bounds"
                  ]
                }
              }
            },
            "required": [
              "generator",
              "version",
              "building_id",
              "building_revision",
              "frame",
              "origin",
              "levels",
              "spaces",
              "probes"
            ]
          },
          "measurements": {
            "type": "array",
            "maxItems": 20,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "id": {
                  "type": "string",
                  "description": "Exact canonical UUID from fresh project research. Never invent one."
                },
                "revision": {
                  "type": "integer",
                  "minimum": 1
                }
              },
              "required": [
                "id",
                "revision"
              ]
            }
          },
          "change_note": {
            "type": "string"
          },
          "request_quote": {
            "type": "string",
            "description": "Exact 1–500 character quote from the CURRENT user request authorising this save."
          }
        },
        "required": [
          "record_id",
          "action",
          "expected_revision",
          "create_area_id",
          "target_revision",
          "title",
          "description",
          "assumptions",
          "recipe",
          "measurements",
          "change_note",
          "request_quote"
        ]
      },
      "handler": "save_project_building_plan",
      "additional_description": "Read exact current physical sources, measurements, target and prior plan. All levels share east +x, north +y, up +z and one explicit origin. Envelope dimensions are outside dimensions; inside dimensions derive from explicit wall thickness. Unknown bounds/heights remain null; above/below prose never creates numeric placement. Explicit source refresh cannot simultaneously move geometry. Saved Concept does not rewrite accepted Building facts. A change is saved only with a successful receipt.",
      "required_parameters": [
        "record_id",
        "action",
        "expected_revision",
        "create_area_id",
        "target_revision",
        "title",
        "description",
        "assumptions",
        "recipe",
        "measurements",
        "change_note",
        "request_quote"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/project-write.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Create or revise a multi-floor coordinate study using existing Building/Level/Space identities, explicit room bounds and floor heights.",
      "description": "",
      "server_fields": [
        "request_quote"
      ]
    },
    "variables": []
  },
