  {
    "key": "tools.save_project_drawing",
    "kind": "tool_contract",
    "label": "Create or revise the existing rectangular, open-top storage-box drawing from four dimensions. This specific legacy tool cannot draw a bed or an arbitrary assembly.",
    "description": "",
    "content": "",
    "definition": {
      "name": "save_project_drawing",
      "description": "Create or revise an exact, editable 2D storage-box drawing inside Bob. Only an open-top rectangular sheet box is supported: full bottom under the walls, front/back between sides. Width/height/depth/thickness drive front, plan, section and finished part dimensions together. No runners, lid, stock-cutting optimisation, fasteners or structural approval. Read the selected target and existing drawings before saving. Make reasonable reversible design choices and identify them as proposals; ask only for missing essential constraints. Do not claim a measured site fit. Every change saves a Concept revision; success requires the returned receipt.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "record_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Existing storage-box artifact UUID to revise, or null to create. Read the current artifact first."
          },
          "create_area_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Exact Area ID on create or null for Project; always null on revision. Never move an existing drawing."
          },
          "expected_revision": {
            "type": "integer",
            "description": "0 for create; exact current artifact revision for edit."
          },
          "target_revision": {
            "type": "integer",
            "description": "Exact current selected target decision for this Project/Area. An inherited Area target uses its Project decision. Read target first; do not invent/select one."
          },
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "assumptions": {
            "type": "string",
