  {
    "key": "tools.save_project_stair",
    "kind": "tool_contract",
    "label": "Save or revise a straight or square-landing quarter-turn stair study linked to an exact house-plan revision. Does not support rounded/winder/spiral stairs.",
    "description": "",
    "content": "",
    "definition": {
      "name": "save_project_stair",
      "description": "Save/revise the requested stair study as a Concept Artifact inside Bob, never as accepted building work. Read and inspect the exact multi-floor plan first; inherit its Project/Area target and measurement evidence. Only straight and square-landing quarter-turn shapes. The server binds the source revision; no copied floor/room geometry allowed. Revising changes only the stair, not its source plan. refresh_source explicitly adopts a newer revision of the SAME plan, preserving every stair parameter; inspect and explain any changed rise/headroom/outlet context. Reuse existing stair ID and revision for changes; never duplicate. Success requires the saved receipt. No form is required of the user.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "record_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "expected_revision": {
            "type": "integer"
          },
          "action": {
            "type": "string",
            "enum": [
              "create",
              "revise",
              "refresh_source"
            ]
          },
          "plan_id": {
            "type": "string"
          },
          "plan_revision": {
            "type": "integer",
            "minimum": 1
          },
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "assumptions": {
            "type": "string"
          },
          "recipe": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "generator": {
                "type": "string",
                "enum": [
                  "stair_study_v1"
                ]
              },
              "version": {
                "type": "integer",
                "enum": [
                  1
                ]
              },
              "from_level_id": {
                "type": "string"
              },
              "to_level_id": {
                "type": "string"
              },
              "start_x_mm": {
                "type": "number",
                "description": "Centre of first riser, at lower floor; shared building x/east datum."
              },
              "start_y_mm": {
                "type": "number",
                "description": "Centre of first riser, shared building y/north datum."
              },
              "heading": {
                "type": "string",
                "enum": [
                  "north",
                  "east",
                  "south",
                  "west"
                ]
              },
              "turn": {
                "type": "string",
                "enum": [
                  "straight",
                  "left",
                  "right"
                ]
              },
              "risers": {
                "type": "integer",
                "minimum": 3,
                "maximum": 60
              },
              "first_flight_risers": {
                "type": [
                  "integer",
                  "null"
                ],
                "description": "Rises to square intermediate landing for a quarter turn; 2 through total-2. Null for straight."
              },
              "width_mm": {
                "type": "integer",
                "description": "Walking strip width, whole mm; no stringers/handrails added."
              },
              "going_mm": {
                "type": "integer"
              },
              "landing_depth_mm": {
                "type": "integer"
              },
              "opening": {
                "type": [
                  "object",
                  "null"
                ],
                "additionalProperties": false,
                "properties": {
                  "x_mm": {
                    "type": "number"
                  },
                  "y_mm": {
                    "type": "number"
                  },
                  "width_mm": {
                    "type": "number"
                  },
                  "depth_mm": {
                    "type": "number"
                  }
                },
                "required": [
                  "x_mm",
                  "y_mm",
                  "width_mm",
                  "depth_mm"
                ],
                "description": "Explicit rectangular floor-opening proposal. Null means unspecified, not a solid/empty floor. Inspect first for a conservative suggestion; do not remove slabs."
              },
              "required_headroom_mm": {
                "type": "integer",
                "description": "Explicit project study criterion, not an automatically determined legal standard."
              },
              "upper_ceiling_above_floor_mm": {
                "type": [
                  "integer",
                  "null"
                ],
                "description": "Flat upper ceiling height above upper finished floor. Null if unknown; never infer it from slab thickness."
              },
              "basis": {
                "type": "string",
                "enum": [
                  "provided_spec",
                  "estimated"
                ]
              },
              "source": {
                "type": "string",
                "description": "Identify actual supplied dimensions or explicit reversible design assumptions."
              }
            },
            "required": [
              "generator",
              "version",
              "from_level_id",
              "to_level_id",
              "start_x_mm",
              "start_y_mm",
              "heading",
              "turn",
              "risers",
              "first_flight_risers",
              "width_mm",
              "going_mm",
              "landing_depth_mm",
              "opening",
              "required_headroom_mm",
              "upper_ceiling_above_floor_mm",
              "basis",
              "source"
            ]
          },
          "change_note": {
            "type": "string"
          },
          "request_quote": {
            "type": "string",
            "description": "Exact quote from CURRENT user request authorising this save."
          }
        },
        "required": [
          "record_id",
          "expected_revision",
          "action",
          "plan_id",
          "plan_revision",
          "title",
          "description",
          "assumptions",
          "recipe",
          "change_note",
          "request_quote"
        ]
      },
      "handler": "save_project_stair",
      "additional_description": "Read the exact parent plan and current stair. Changes affect only the stair artifact. Explicit refresh keeps stair parameters but may change derived height and context; explain the result. Openings are conservative geometric suggestions, not cutting instructions. Never equate a projected rectangle or modelled_checks_only with a safe buildable stair. Preserve exact source/target/measurement revisions. A change is saved only with a successful receipt.",
      "required_parameters": [
        "record_id",
        "expected_revision",
        "action",
        "plan_id",
        "plan_revision",
        "title",
        "description",
        "assumptions",
        "recipe",
        "change_note",
        "request_quote"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/project-write.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Save or revise a straight or square-landing quarter-turn stair study linked to an exact house-plan revision. Does not support rounded/winder/spiral stairs.",
      "description": "",
      "server_fields": [
        "request_quote"
      ]
    },
    "variables": []
  },
