  {
    "key": "tools.search_material_catalog",
    "kind": "tool_contract",
    "label": "Search reusable material and part definitions by material/form categories and typed properties. Also browse available profiles/categories. This is not stock or Shopping.",
    "description": "",
    "content": "",
    "definition": {
      "name": "search_material_catalog",
      "description": "Browse categories/profiles, or search current reusable material/part definitions. Supply every required field, using null for unused nullable filters. For entity=categories or profiles use categories=[], profile_code=null, profile_revision=null, properties={}. query=null browses all; never use an empty string. Copy returned codes/revisions, then read the exact profile before saving; do not guess vocabulary. Not inventory or a Shopping list. Follow next_cursor. A failed request is not absence.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "entity": {
            "type": "string",
            "enum": [
              "categories",
              "profiles",
              "materials",
              "parts"
            ]
          },
          "query": {
            "type": [
              "string",
              "null"
            ]
          },
          "categories": {
            "type": "array",
            "maxItems": 12,
            "uniqueItems": true,
            "items": {
              "type": "string"
            },
            "description": "Exact category codes, e.g. wood and sheet. Parent categories include descendants. Empty for vocabulary browsing."
          },
          "profile_code": {
            "type": [
              "string",
              "null"
            ]
          },
          "profile_revision": {
            "type": [
              "integer",
              "null"
            ]
          },
          "properties": {
            "type": "object",
            "description": "Property keys come from read_material_catalog(profile). Each value has exactly value, unit, truth, parameter and note. Quantities are strings, not floats; decimal inputs have at most six decimals. Modern inch/tum uses unit=in and a separate value, e.g. 0.75, 0,75, 3/4, 1 1/2 or ¾. SQL converts exactly to mm before search/save; do not pre-round or put unit suffixes in value. Nominal trade sizes (2x4, R 1/2) belong in nominal_size text/aliases, NEVER in a numeric dimension; retain independently specified dimensions or explicit unknowns. A part may use value=null, truth=provided_spec and a named parameter; unknown requires a note. Search filters must be known, non-parameter values. A profile and exact revision are required for typed property filters.",
            "additionalProperties": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "value": {
                  "type": [
                    "string",
                    "boolean",
                    "null"
                  ]
                },
                "unit": {
                  "type": [
                    "string",
                    "null"
                  ]
                },
                "truth": {
                  "type": "string",
                  "enum": [
                    "provided_spec",
                    "estimated",
                    "unknown"
                  ]
                },
                "parameter": {
                  "type": [
                    "string",
                    "null"
                  ]
                },
                "note": {
                  "type": "string"
                }
              },
              "required": [
                "value",
                "unit",
                "truth",
                "parameter",
                "note"
              ]
            }
          },
          "after": {
            "type": [
              "string",
              "null"
            ],
            "description": "Copy next_cursor or null."
          }
        },
        "required": [
          "entity",
          "query",
          "categories",
          "profile_code",
          "profile_revision",
          "properties",
          "after"
        ]
      },
      "handler": "search_material_catalog",
      "additional_description": "Search first; follow pages or widen a title query. Matching names are candidates, not equivalence. Read the exact profile for field types and units; use its version for property filters. Unknown values never match everything. A failed read is not proof of absence. Shared definitions and the current project only. No images, stock quantities or other projects are read. Modern inch/tum input uses unit=in and a separate value string such as 0.75, 3/4, 1 1/2 or ¾. Do not calculate a rounded mm value yourself: SQL normalizes search and saves exactly to mm. Unit suffixes belong in unit, not value. Non-terminating or overprecise results are rejected, not rounded. A nominal trade size such as 2x4 or R 1/2 is text, not a physical dimension: use nominal_size/aliases and separately sourced working dimensions. Never infer actual timber dimensions, pipe bore or historic Swedish inches from a trade name. Missing working dimensions remain unknown until specified; a design assumption is not measured evidence.",
      "required_parameters": [
        "entity",
        "query",
        "categories",
        "profile_code",
        "profile_revision",
        "properties",
        "after"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/material-catalog.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Search reusable material and part definitions by material/form categories and typed properties. Also browse available profiles/categories. This is not stock or Shopping.",
      "description": ""
    },
    "variables": []
  },
  {
    "key": "tools.search_project_data",
    "kind": "tool_contract",
    "label": "Inspect authorised project records relevant to the question: measurements, materials, tasks, buildings, solutions and saved drawing recipes. Follow pages or read an exact record; an empty filtered page is not an empty project.",
    "description": "",
    "content": "",
    "definition": {
      "name": "search_project_data",
      "description": "inspect authorised project records relevant to the question.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "dataset": {
            "type": "string",
            "enum": [
              "project",
              "areas",
              "tasks",
              "materials",
              "crew",
              "events",
              "announcements",
              "measurements",
              "components",
              "solutions",
              "target",
              "artifacts",
              "requirements",
              "physical_spaces",
              "physical_elements",
              "physical_buildings",
              "physical_levels",
              "physical_relationships",
              "physical_proposals",
              "physical_space_measurements",
              "plan"
            ],
            "description": "physical_buildings/levels/spaces/elements/relationships and physical_space_measurements expose only current context scoped to this project; plan exposes the approved living Project Plan or an exact proposal revision; physical_proposals is separate and never accepted reality. Query can match a known building_id to narrow a physical dataset. Above/below is topology, not measured alignment; connects_to is not an inferred door. Measurements, components, selected target, solutions, artifacts (text and supported parametric recipes with deterministic part dimensions, not pixels), requirements and collaboration data. Follow next_cursor with after_id using identical filters."
          },
          "query": {
            "type": [
              "string",
              "null"
            ],
            "description": "Literal search text, max 200 characters."
          },
          "status": {
            "type": [
              "string",
              "null"
            ],
            "description": "Task, material or event status only; otherwise null."
          },
          "area_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Exact area id for task/design datasets; otherwise null. For target: an empty area result inherits record_id=project; an explicit row with null solution_id means cleared, not inherited."
          },
          "after_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Pagination: copy next_cursor from the previous result, keep filters unchanged. Start with null."
          },
          "record_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Exact record id, or null. For plan, use the revision as a string to read a saved proposal or historical plan; null reads only the approved plan. The pending proposal record_id is in the project working_plan briefing. Other plan filters must be null."
          }
        },
        "required": [
          "dataset",
          "query",
          "status",
          "area_id",
          "record_id",
          "after_id"
        ]
      },
      "handler": "search_project_data",
      "additional_description": "Read only the active project. Use the exact dataset and IDs exposed by the schema. Keep truth states and conflicting evidence. Search again or follow next_cursor when results are partial. Images use list_project_category/open_project_item, not this record search.",
      "required_parameters": [
        "dataset",
        "query",
        "status",
        "area_id",
        "record_id",
        "after_id"
      ],
      "optional_parameters": [],
      "envelope": {
        "type": "function",
        "schema_version": 1,
        "arguments": "JSON object validated against parameters; project binding and write provenance remain server-owned."
      },
      "expected_return": {
        "format": "json",
        "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."
      }
    },
    "metadata": {
      "migrated_from": "supabase/functions/_shared/project-lookup.ts",
      "source_revision": "e0d5fcd4f212cb42743309ee0c0b5e8e37756d6d",
      "seed_version": 1,
      "label": "Inspect authorised project records relevant to the question: measurements, materials, tasks, buildings, solutions and saved drawing recipes. Follow pages or read an exact record; an empty filtered page is not an empty project.",
      "description": ""
